namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    public int DiscountCentsFor(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents * RatePercent(tier) / 100;

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}
E
python3 - <<'E'
p='src/CheckoutPricing.Application/CalculateLoyaltyDiscount.cs'
s=open(p).read()
s=s.replace('''    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query) =>
        new(query.SubtotalCents, 0, query.SubtotalCents, query.LoyaltyTier);''','''    private readonly LoyaltyDiscountPolicy _policy = new();

    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var discount = _policy.DiscountCentsFor(query.SubtotalCents, query.LoyaltyTier);
        return new(query.SubtotalCents, discount, query.SubtotalCents - discount, query.LoyaltyTier);
    }''')
open(p,'w').write(s)
E
