namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    public int DiscountCentsFor(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents * RatePercent(tier) / 100;

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}

namespace CheckoutPricing.Domain;

public sealed class PromoCodePolicy
{
    private const int Welcome5Cents = 500;
    private const int Summer10MaxCents = 1_500;

    public int DiscountCentsFor(string? code, int subtotalCents, int loyaltyCents) =>
        code?.ToUpperInvariant() switch
        {
            "WELCOME5" => Welcome5Cents,
            "SUMMER10" => Math.Min((subtotalCents - loyaltyCents) / 10, Summer10MaxCents),
            _ => 0
        };
}

namespace CheckoutPricing.Domain;

public sealed class DiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;

    private readonly LoyaltyDiscountPolicy _loyalty = new();
    private readonly PromoCodePolicy _promo = new();

    public int DiscountCentsFor(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyalty = LoyaltyCentsFor(subtotalCents, tier);
        var promo = _promo.DiscountCentsFor(promoCode, subtotalCents, loyalty);
        return Math.Min(loyalty + promo, subtotalCents);
    }

    private int LoyaltyCentsFor(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(_loyalty.DiscountCentsFor(subtotalCents, tier), LoyaltyCapCents);
}

namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    public int DiscountCentsFor(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents * RatePercent(tier) / 100;

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}

namespace CheckoutPricing.Domain;

public sealed class PromoCodePolicy
{
    private const int Welcome5Cents = 500;
    private const int Summer10MaxCents = 1_500;

    public int DiscountCentsFor(string? code, int subtotalCents, int loyaltyCents) =>
