namespace CheckoutPricing.Domain;

public sealed class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public int FeeCentsFor(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFeeFor(tier) : StandardFeeFor(payableTotalCents, tier);

    private static int ExpressFeeFor(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFeeFor(int payableTotalCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCents;
}

